CREATE TABLE retention_guards(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,customer_id TEXT NOT NULL,checked_at INTEGER NOT NULL,FOREIGN KEY(tenant_id,customer_id) REFERENCES customers(tenant_id,id));
CREATE TRIGGER retention_guard BEFORE INSERT ON retention_guards BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM customers c JOIN tenants t ON t.id=c.tenant_id WHERE c.id=NEW.customer_id AND c.tenant_id=NEW.tenant_id AND t.retention_days>0 AND c.phone NOT LIKE 'deleted:%' AND MAX(c.created_at,COALESCE((SELECT MAX(b.ends_at) FROM bookings b WHERE b.tenant_id=c.tenant_id AND b.customer_id=c.id),0))<NEW.checked_at-t.retention_days*86400000) THEN RAISE(ABORT,'customer_recently_active') END; END;
